const raw = $input.first().json.message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    throw new Error('OpenAI output not parseable: ' + raw);
  }
}

const leadId = `BTP-${new Date().toISOString().slice(0,10)}-${Math.random().toString(36).substr(2,4).toUpperCase()}`;
const originalEmail = $('Gmail Trigger').first().json;

return [{
  json: {
    ...parsed,
    lead_id: leadId,
    email_original_from: originalEmail.from,
    email_original_subject: originalEmail.subject,
    email_original_date: originalEmail.date,
    processed_at: new Date().toISOString()
  }
}];

